import type { Viseme } from './types';
// Generated by the voice agent: { [char]: [ [startFrame, shape], ... ] } sorted by frame.
import data from '../data/visemes.json';
const V = data as unknown as Record<string, [number, Viseme][]>;
/** Mouth shape for a character at an absolute film frame (X when silent). */
export const visemeAt = (char: string, frame: number): Viseme => {
  const arr = V[char];
  if (!arr || arr.length === 0) return 'X';
  let lo = 0, hi = arr.length - 1, ans = -1;
  while (lo <= hi) { const m = (lo + hi) >> 1; if (arr[m][0] <= frame) { ans = m; lo = m + 1; } else hi = m - 1; }
  return ans < 0 ? 'X' : arr[ans][1];
};
/** True if character is speaking at frame (non-X shape). */
export const isTalking = (char: string, frame: number) => visemeAt(char, frame) !== 'X';
